import java.util.Objects;

import org.springframework.http.HttpStatus;
import org.springframework.http.ProblemDetail;
import org.springframework.http.ResponseEntity;
import org.springframework.stereotype.Service;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.RestControllerAdvice;

@Service
public class InvoiceCancellationService {

    private final InvoiceRepository invoiceRepository;

    public InvoiceCancellationService(InvoiceRepository invoiceRepository) {
        this.invoiceRepository = Objects.requireNonNull(invoiceRepository);
    }

    public void cancelInvoice(long invoiceId, long customerId) {
        Invoice invoice = invoiceRepository.findById(invoiceId)
                .orElseThrow(() -> new InvoiceNotFoundException(invoiceId));

        if (invoice.customerId() != customerId) {
            throw new InvoiceCancellationForbiddenException(invoiceId);
        }

        if (!"UNPAID".equals(String.valueOf(invoice.status()))) {
            throw new InvoiceNotCancellableException(invoiceId);
        }

        invoice.markCancelled();
    }

    public static final class InvoiceNotFoundException extends RuntimeException {
        public InvoiceNotFoundException(long invoiceId) {
            super("Invoice " + invoiceId + " was not found");
        }
    }

    public static final class InvoiceCancellationForbiddenException
            extends RuntimeException {
        public InvoiceCancellationForbiddenException(long invoiceId) {
            super("Customer is not allowed to cancel invoice " + invoiceId);
        }
    }

    public static final class InvoiceNotCancellableException
            extends RuntimeException {
        public InvoiceNotCancellableException(long invoiceId) {
            super("Invoice " + invoiceId + " is not unpaid");
        }
    }
}

