class InvoiceCancellationExceptionHandler {

    @ExceptionHandler(InvoiceCancellationService.InvoiceNotFoundException.class)
    ResponseEntity<ProblemDetail> handleNotFound(
            InvoiceCancellationService.InvoiceNotFoundException exception) {
        return problem(HttpStatus.NOT_FOUND, exception);
    }

    @ExceptionHandler(
            InvoiceCancellationService.InvoiceCancellationForbiddenException.class)
    ResponseEntity<ProblemDetail> handleForbidden(
            InvoiceCancellationService.InvoiceCancellationForbiddenException exception) {
        return problem(HttpStatus.FORBIDDEN, exception);
    }

    @ExceptionHandler(
            InvoiceCancellationService.InvoiceNotCancellableException.class)
    ResponseEntity<ProblemDetail> handleConflict(
            InvoiceCancellationService.InvoiceNotCancellableException exception) {
        return problem(HttpStatus.CONFLICT, exception);
